package com.voidlessstar.modtitle.mixin;

import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import com.mojang.blaze3d.platform.IconSet;
import com.mojang.blaze3d.platform.Window;
import net.minecraft.server.packs.PackResources;
import net.minecraft.server.packs.resources.IoSupplier;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Redirect;

@Mixin(Window.class)
public class WindowIconMixin {
    private static final String ICON_16 = join("");
    private static final String ICON_32 = join("");
    private static final String ICON_48 = join("");
    private static final String ICON_128 = join("", "");
    private static final String ICON_256 = join("", "", "", "", "", "");

    private static String join(String... parts) {
        StringBuilder sb = new StringBuilder();
        for (String p : parts) sb.append(p);
        return sb.toString();
    }

    @Redirect(
        method = "setIcon",
        at = @At(value = "INVOKE", target = "Lcom/mojang/blaze3d/platform/IconSet;getStandardIcons(Lnet/minecraft/server/packs/PackResources;)Ljava/util/List;"),
        require = 0
    )
    private List<IoSupplier<InputStream>> modtitle$overrideWindowIcons(IconSet instance, PackResources pack) {
        List<IoSupplier<InputStream>> icons = new ArrayList<>();
        java.util.Base64.Decoder decoder = java.util.Base64.getDecoder();
        String[] data = { ICON_16, ICON_32, ICON_48, ICON_128, ICON_256 };
        for (String encoded : data) {
            byte[] bytes = decoder.decode(encoded);
            icons.add(() -> new ByteArrayInputStream(bytes));
        }
        return icons;
    }
}
